UPDATE cfg_draft
   SET spec = #{row.spec}::jsonb,
       revision = #{row.revision},
       based_on_version = #{row.basedOnVersion},
       update_at = #{row.updateAt},
       update_by = #{row.updateBy}
 WHERE object_type = #{row.objectType}
   AND object_id = #{row.objectId}
   AND revision = #{expectedRevision}
